import * as Schema from "effect/Schema";

// Entity IDs are UUIDv7s generated by the client, so creates can be retried safely.
const Uuid = Schema.String.check(Schema.isUUID());

export const GroupId = Uuid.pipe(Schema.brand("GroupId"));
export type GroupId = typeof GroupId.Type;

export const PlayerId = Uuid.pipe(Schema.brand("PlayerId"));
export type PlayerId = typeof PlayerId.Type;

export const SessionId = Uuid.pipe(Schema.brand("SessionId"));
export type SessionId = typeof SessionId.Type;

export const EntryId = Uuid.pipe(Schema.brand("EntryId"));
export type EntryId = typeof EntryId.Type;

export const StakeId = Uuid.pipe(Schema.brand("StakeId"));
export type StakeId = typeof StakeId.Type;

export const VenueId = Uuid.pipe(Schema.brand("VenueId"));
export type VenueId = typeof VenueId.Type;

/** Clerk's user ID (`user_…`), not a UUID. */
export const UserId = Schema.NonEmptyString.pipe(Schema.brand("UserId"));
export type UserId = typeof UserId.Type;

export const InviteId = Uuid.pipe(Schema.brand("InviteId"));
export type InviteId = typeof InviteId.Type;
